from fastapi import FastAPI, UploadFile, File, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from PIL import Image
import io

app = FastAPI(title="Smart CropCare AI Engine", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.post("/predict")
async def predict_crop_disease(file: UploadFile = File(...)):
    try:
        contents = await file.read()
        if not contents:
            raise HTTPException(status_code=400, detail="Nta foto yoherejwe.")
            
        img = Image.open(io.BytesIO(contents)).convert("RGB")
        
        # =========================================================
        # AI SAFETY & CONTENT FILTER (Gushungura icyo ari cyo)
        # =========================================================
        # Hano ni ho AI model (nka MobileNetV2 / CLIP / ImageNet Classifier) 
        # yagenzura niba ifoto ari iy'igihingwa cyangwa niba ari umuntu/ikindi kintu.
        # Urugero rwa Code y'icyitegererezo (Prototype):
        
        is_plant_leaf = True  # Hindura iyi igendeye kuri Model y'ukuri uyikoresha
        is_human_or_other = False # Niba ari umuntu cyangwa ikindi kintu kitari igihingwa

        if is_human_or_other:
            return {
                "success": False,
                "message": "Nyamuneka shyiraho ifoto y'ikibabi cyangwa igice cy'igihingwa, iyi foto si iy'igihingwa."
            }
        
        # Niba ari igihingwa koko, ikomeza gusuzuma indwara:
        detected_disease = "Potato - Late Blight (Ububore bw'ikirayi)"
        confidence_score = "97.5%"
        recommendation = "Spreya imiti yica uyunguyungu (Fungicide) mu gitondo kare."

        return {
            "success": True,
            "crop_name": "Birayi (Potato)",
            "disease": detected_disease,
            "confidence": confidence_score,
            "recommendation": recommendation
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)